function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 20);
  ctx.lineTo(W / 2, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2 - 20, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2 + 20, H / 2 + 70);
  ctx.stroke();

  // draw food
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W / 2 + 50 + 20 * Math.sin(t), H / 2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2 + 50 + 20 * Math.cos(t), H / 2 - 40, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2 + 50 + 20 * Math.sin(t + Math.PI / 2), H / 2 - 60, 10, 0, 2 * Math.PI);
  ctx.fill();

  // draw benefit lines
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W / 2 + 70, H / 2 - 20);
  ctx.lineTo(W / 2 + 90 + 10 * Math.sin(t), H / 2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 70, H / 2 - 40);
  ctx.lineTo(W / 2 + 90 + 10 * Math.cos(t), H / 2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 70, H / 2 - 60);
  ctx.lineTo(W / 2 + 90 + 10 * Math.sin(t + Math.PI / 2), H / 2 - 60);
  ctx.stroke();

  ctx.restore();
}
